export function adsTag() { return ADSENSE ? '<meta name="google-adsense-account" content="' + ADSENSE + '"><script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=' + ADSENSE + '" crossorigin="anonymous"></script>' : ""; }
export function layout(title, desc, body, path, origin, extra) {
  return '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + title + ' | QuickToolHub</title><meta name="description" content="' + desc + '"><link rel="canonical" href="' + origin + path + '">' + ((extra || "").indexOf('name="robots"') > -1 ? "" : '<meta name="robots" content="index,follow">') + '<meta property="og:title" content="' + title + ' | QuickToolHub"><meta property="og:description" content="' + desc + '"><meta property="og:type" content="website"><meta property="og:url" content="' + origin + path + '"><meta property="og:site_name" content="QuickToolHub"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="' + title + ' | QuickToolHub"><meta name="twitter:description" content="' + desc + '"><meta property="og:image" content="' + origin + '/og-image.png"><meta name="twitter:image" content="' + origin + '/og-image.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,700;12..96,800&family=Figtree:wght@400;500;600;700&display=swap" rel="stylesheet">' + ((extra || "").indexOf("noindex") > -1 ? '<meta name="google-adsense-account" content="' + ADSENSE + '">' : adsTag()) + HEADBITS + (extra || "") + '<style>' + LCSS + '</style></head><body><header><div class="nav"><a class="logo" href="/">QuickTool<b>Hub</b></a><nav><a href="/">Home</a><a href="/tools">All Tools</a><a href="/blog">Blog</a><a href="/how-to-use">How to Use</a><a href="/about">About</a><a href="/contact">Contact</a></nav></div></header><main>' + body.split("{{MAIL}}").join(MAIL) + '</main><footer><div><a href="/tools">All Tools</a><a href="/blog">Blog</a><a href="/how-to-use">How to Use</a><a href="/about">About Us</a><a href="/contact">Contact Us</a><a href="/privacy-policy">Privacy Policy</a><a href="/terms">Terms &amp; Conditions</a><a href="/disclaimer">Disclaimer</a><a href="/editorial-policy">Editorial Policy</a></div><p>© 2026 QuickToolHub. All rights reserved. Contact: <a href="mailto:' + MAIL + '">' + MAIL + '</a></p></footer></body></html>';
}
